def valid(text):
    """题面契约：第一行数据组数 k（题面未给上界，只要求正整数）；每组两行：N（4<=N<=8），
    以及 N 个 1..13 的整数点数，单空格分隔。"""
    if not text.endswith("\n"):
        return False
    lines = text[:-1].split("\n")
    if not lines[0].isdigit() or lines[0] != str(int(lines[0])) or int(lines[0]) < 1:
        return False
    k = int(lines[0])
    if len(lines) != 2 * k + 1:
        return False
    for i in range(k):
        a, b = lines[1 + 2 * i], lines[2 + 2 * i]
        if a not in {"4", "5", "6", "7", "8"}:
            return False
        parts = b.split(" ")
        if len(parts) != int(a) or not all(p.isdigit() and p == str(int(p)) and 1 <= int(p) <= 13 for p in parts):
            return False
    return True

def valid(text):
    """题面：输入只含一个整数 n（1 <= n <= 1000）。"""
    if not text.endswith("\n"):
        return False
    lines = text.split("\n")[:-1]
    if len(lines) != 1 or not lines[0].isdigit() or lines[0][0] == "0":
        return False
    return 1 <= int(lines[0]) <= 1000

def valid(text):
    """题面：第一行 t (1<=t<=100)，接下来 t 行各一个整数 n (1<=n<=10^6)。"""
    if not text.endswith("\n"):
        return False
    lines = text[:-1].split("\n")
    if not all(re.fullmatch(r"[1-9][0-9]*", x) for x in lines):
        return False
    t = int(lines[0])
    if not (1 <= t <= 100) or len(lines) != t + 1:
        return False
    return all(1 <= int(x) <= 10**6 for x in lines[1:])

def valid(text):
    """题面：一行字符串 s，由 ASCII 数字和大小写字母组成，0 < len(s) < 10^5。"""
    if not text.endswith("\n") or text.count("\n") != 1:
        return False
    s = text[:-1]
    return 0 < len(s) < 10**5 and re.fullmatch(r"[0-9A-Za-z]+", s) is not None

def valid(text):
    """题面：第一行 coins（1<=长度<=12，1<=coins[i]<=2^31-1，空格分隔），第二行 amount（0<=amount<=10^4）。"""
    if not text.endswith("\n"):
        return False
    lines = text[:-1].split("\n")
    if len(lines) != 2:
        return False
    parts = lines[0].split(" ")
    if not (1 <= len(parts) <= 12) or not all(re.fullmatch(r"[1-9][0-9]*", x) for x in parts):
        return False
    if not all(1 <= int(x) <= MAXC for x in parts):
        return False
    if not re.fullmatch(r"0|[1-9][0-9]*", lines[1]):
        return False
    return 0 <= int(lines[1]) <= 10**4

def valid(text):
    """题面：n m (1<=n,m<=1e5)；n 个 d_i (0<=d_i<=m)；m 个 a_i (1<=a_i<=1e5)。"""
    if not text.endswith("\n"):
        return False
    lines = text[:-1].split("\n")
    if len(lines) != 3:
        return False
    rows = [ln.split(" ") for ln in lines]
    for row in rows:
        if not all(re.fullmatch(r"0|[1-9][0-9]*", x) for x in row):
            return False
    if len(rows[0]) != 2:
        return False
    n, m = map(int, rows[0])
    if not (1 <= n <= 10**5 and 1 <= m <= 10**5):
        return False
    if len(rows[1]) != n or len(rows[2]) != m:
        return False
    if not all(0 <= int(x) <= m for x in rows[1]):
        return False
    return all(1 <= int(x) <= 10**5 for x in rows[2])

def valid(text):
    """题面：第一行 N（1<=N<=10）；4 行各 6 个大写字母；N 行单词，各 1~4 个大写字母。"""
    if not text.endswith("\n"):
        return False
    lines = text[:-1].split("\n")
    if not re.fullmatch(r"[1-9][0-9]*", lines[0]):
        return False
    n = int(lines[0])
    if not (1 <= n <= 10) or len(lines) != 5 + n:
        return False
    if not all(re.fullmatch(r"[A-Z]{6}", x) for x in lines[1:5]):
        return False
    return all(re.fullmatch(r"[A-Z]{1,4}", x) for x in lines[5:])

def valid(text):
    """题面：第一行 m n（1<=m,n<=200），接下来 m 行每行 n 个整数，0<=h<=2*10^4。"""
    if not text.endswith('\n'):
        return False
    lines = text[:-1].split('\n')
    try:
        mn = lines[0].split(' ')
        if len(mn) != 2:
            return False
        m, n = map(int, mn)
        if not (1 <= m <= 200 and 1 <= n <= 200) or len(lines) != m + 1:
            return False
        for ln in lines[1:]:
            row = ln.split(' ')
            if len(row) != n:
                return False
            for v in row:
                if not 0 <= int(v) <= 20000:
                    return False
    except ValueError:
        return False
    return True

def valid(text):
    """题面：第一行 n m（1<=n<=110, 1<=m<=10000），接下来恰好 m 行，每行两个顶点编号 u v，编号在 0..n-1。"""
    if not text.endswith("\n"):
        return False
    lines = text[:-1].split("\n")
    if not lines or not INT_LINE.fullmatch(lines[0]):
        return False
    n, m = map(int, lines[0].split())
    if not (1 <= n <= 110 and 1 <= m <= 10000) or len(lines) != m + 1:
        return False
    for line in lines[1:]:
        if not INT_LINE.fullmatch(line):
            return False
        u, v = map(int, line.split())
        if not (u < n and v < n):
            return False
    return True

def valid(text):
    """题面：1≤n≤2e5，0≤k≤n；第二行恰 n 个整数，1≤a_i≤1e9。"""
    if not text.endswith('\n'):
        return False
    lines = text[:-1].split('\n')
    if len(lines) != 2:
        return False
    h = lines[0].split(' ')
    if len(h) != 2 or not all(_int(t) for t in h):
        return False
    n, k = map(int, h)
    if not (1 <= n <= 2 * 10 ** 5 and 0 <= k <= n):
        return False
    a = lines[1].split(' ')
    if len(a) != n or not all(_int(t) for t in a):
        return False
    return all(1 <= int(t) <= MAXV for t in a)

