    assert r.returncode==0,(n,'validator execution failed');bad=json.loads(r.stdout);text=validator.read_text();node=next(x for x in ast.parse(text).body if isinstance(x,ast.FunctionDef) and x.name=='valid');c['contract']={'cases':len(records),'rejected':bad,'definition':ast.get_source_segment(text,node)};write(output,result)
