    c['platform']={'final':attempts[-1]['verdict'],'attempts':attempts,'checked_at':now()};write(output,result)
   row['passed']=not c['statement']['changed_fields'] and all(f['matches'] for f in c['readback']['files']) and not c['contract']['rejected'] and all(f['matches'] for f in c['answers']['files']) and c['local']['status']=='Accepted' and c['local'].get('timing_audit',{}).get('status')=='passed' and c.get('platform',{}).get('final')=='Accepted';row['complete']=True;row.pop('error',None)
   print(n,'PASS' if row['passed'] else 'HOLD',c['local']['status'],c.get('platform',{}).get('final'),flush=True)
  except Exception as exc:row['error']=type(exc).__name__+': '+str(exc)[:180];print(n,'ERROR',row['error'],flush=True)
  write(output,result)
 result['finished_at']=now();result['procedures']=[{'filename':Path(p).name,'sha256':sha(p),'source':Path(p).read_text()} for p in [__file__,oracle_path]];write(output,result)
